True from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        if row[0] != background and all(value == row[0] for value in row):
            out[r] = [2] * w
    for c in range(w):
        value = grid[0][c]
        if value != background and all(grid[r][c] == value for r in range(h)):
            for r in range(h):
                out[r][c] = 2
    return out
